const n="# 📘 第4课：高精度加法\n\n> **课程定位**：高精度系列第一课 —— 100% 掌握高精度加法\n\n---\n\n## 一、学习目标\n\n通过本课学习，你将能够：\n\n1. ✅ 理解为什么需要高精度算法\n2. ✅ 掌握字符串转数组的方法（倒序存储）\n3. ✅ 完全理解竖式加法的模拟过程\n4. ✅ 独立编写高精度加法程序\n\n---\n\n## 二、为什么需要高精度？\n\n### 2.1 普通整数的局限\n\n```cpp\n#include <iostream>\nusing namespace std;\n\nint main() {\n    int a = 2147483647;      // int 最大值\n    cout << a + 1 << endl;   // 溢出！输出 -2147483648\n\n    long long b = 9223372036854775807LL;  // long long 最大值\n    cout << b + 1 << endl;   // 溢出！\n\n    return 0;\n}\n```\n\n**问题**：当数字超过数据类型的表示范围时，会发生溢出！\n\n### 2.2 什么情况需要高精度？\n\n- 计算 100! = 93326215443944152681699238856...（158 位数）\n- 两个 1000 位的大整数相加\n- 密码学中的大数运算\n\n### 2.3 解决思路\n\n既然计算机的基本类型存不下，我们就用数组来存储每一位！\n\n```\n大数：123456789012345678901234567890\n数组：[0,9,8,7,6,5,4,3,2,1,0,9,8,7,6,5,4,3,2,1,0,9,8,7,6,5,4,3,2,1]\n      个位 十位 ...                                              高位\n```\n\n---\n\n## 三、核心思想：模拟竖式加法\n\n### 3.1 回顾小学竖式加法\n\n```\n    1 2 3 4\n  +   5 6 7\n  ---------\n    1 8 0 1\n```\n\n计算过程：\n\n1. 个位：4 + 7 = 11，写 1 进 1\n2. 十位：3 + 6 + 1(进位) = 10，写 0 进 1\n3. 百位：2 + 5 + 1(进位) = 8，写 8 进 0\n4. 千位：1 + 0 + 0(进位) = 1，写 1\n\n### 3.2 程序模拟的关键点\n\n| 要点         | 说明                                             |\n| ------------ | ------------------------------------------------ |\n| 倒序存储     | 个位在 a[0]，方便对齐和处理进位                  |\n| 逐位相加     | 从低位到高位依次计算                             |\n| 处理进位     | sum >= 10 时，进位 = sum / 10，当前位 = sum % 10 |\n| 处理不同位数 | 短的数高位补 0                                   |\n\n### 3.3 图示\n\n```\n        a:  9  8  7  6  5  4  3  2  1    （987654321 倒序）\n        b:        8  7  6  5  4  3  2    （ 87654321 倒序）\n  ----------------------------------------\n  进位 carry:   1  1  1  1  1  1  1  0\n  ----------------------------------------\n  结果 c:  5  7  4  3  2  1  0  9  7  1  （1075308642 倒序）\n```\n\n---\n\n## 四、代码实现\n\n### 4.1 版本一：使用字符串（更接近真实输入）\n\n```cpp\n#include <iostream>\n#include <string>\nusing namespace std;\n\n// 高精度加法\nstring add(string num1, string num2) {\n    // 1. 将字符串转为数组（倒序）\n    int a[1010] = {0}, b[1010] = {0}, c[1010] = {0};\n    int len1 = num1.length();\n    int len2 = num2.length();\n\n    for (int i = 0; i < len1; i++) {\n        a[i] = num1[len1 - 1 - i] - '0';\n    }\n    for (int i = 0; i < len2; i++) {\n        b[i] = num2[len2 - 1 - i] - '0';\n    }\n\n    // 2. 逐位相加\n    int len = max(len1, len2);\n    int carry = 0;  // 进位\n\n    for (int i = 0; i < len; i++) {\n        int sum = a[i] + b[i] + carry;\n        c[i] = sum % 10;      // 当前位\n        carry = sum / 10;     // 进位\n    }\n\n    // 3. 处理最高进位\n    if (carry > 0) {\n        c[len] = carry;\n        len++;\n    }\n\n    // 4. 转回字符串（倒序输出）\n    string result = \"\";\n    for (int i = len - 1; i >= 0; i--) {\n        result += (char)(c[i] + '0');\n    }\n\n    return result;\n}\n\nint main() {\n    string a, b;\n    cin >> a >> b;\n    cout << add(a, b) << endl;\n    return 0;\n}\n```\n\n### 4.2 版本二：使用 vector（更简洁）\n\n```cpp\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\n// 字符串转 vector（倒序）\nvector<int> stringToVec(string s) {\n    vector<int> v;\n    for (int i = s.length() - 1; i >= 0; i--) {\n        v.push_back(s[i] - '0');\n    }\n    return v;\n}\n\n// vector 转字符串\nstring vecToString(vector<int> v) {\n    string s = \"\";\n    for (int i = v.size() - 1; i >= 0; i--) {\n        s += (char)(v[i] + '0');\n    }\n    return s;\n}\n\n// 高精度加法\nvector<int> add(vector<int> a, vector<int> b) {\n    vector<int> c;\n    int carry = 0;\n\n    for (int i = 0; i < a.size() || i < b.size() || carry; i++) {\n        int sum = carry;\n        if (i < a.size()) sum += a[i];\n        if (i < b.size()) sum += b[i];\n        c.push_back(sum % 10);\n        carry = sum / 10;\n    }\n\n    return c;\n}\n\nint main() {\n    string s1, s2;\n    cin >> s1 >> s2;\n\n    vector<int> a = stringToVec(s1);\n    vector<int> b = stringToVec(s2);\n    vector<int> c = add(a, b);\n\n    cout << vecToString(c) << endl;\n    return 0;\n}\n```\n\n### 4.3 版本三：使用数组函数封装\n\n```cpp\n#include <iostream>\n#include <cstring>\nusing namespace std;\n\nconst int MAXN = 1010;\n\n// 高精度加法：c = a + b\n// 数组第 0 位存长度\nvoid add(int a[], int b[], int c[]) {\n    int lenA = a[0], lenB = b[0];\n    int len = max(lenA, lenB);\n    int carry = 0;\n\n    for (int i = 1; i <= len; i++) {\n        int sum = carry;\n        if (i <= lenA) sum += a[i];\n        if (i <= lenB) sum += b[i];\n        c[i] = sum % 10;\n        carry = sum / 10;\n    }\n\n    if (carry > 0) {\n        len++;\n        c[len] = carry;\n    }\n\n    c[0] = len;  // 存储结果长度\n}\n\n// 字符串转数组\nvoid stringToArray(string s, int a[]) {\n    int len = s.length();\n    a[0] = len;  // 第 0 位存长度\n    for (int i = 1; i <= len; i++) {\n        a[i] = s[len - i] - '0';  // 倒序存入\n    }\n}\n\n// 输出数组\nvoid printArray(int a[]) {\n    for (int i = a[0]; i >= 1; i--) {\n        cout << a[i];\n    }\n    cout << endl;\n}\n\nint main() {\n    string s1, s2;\n    cin >> s1 >> s2;\n\n    int a[MAXN] = {0}, b[MAXN] = {0}, c[MAXN] = {0};\n    stringToArray(s1, a);\n    stringToArray(s2, b);\n    add(a, b, c);\n    printArray(c);\n\n    return 0;\n}\n```\n\n---\n\n## 五、关键细节解析\n\n### 5.1 为什么要倒序存储？\n\n**对齐方便**：两个不同位数的数相加时，个位自动对齐。\n\n```\n正序存储（不好）：     倒序存储（好）：\na: 1 2 3              a: 3 2 1\nb: 4 5                b: 5 4\n   ↓ 怎么对齐？          ↓ 自动对齐！\n```\n\n**进位方便**：进位总是向数组下标更大的方向传递。\n\n### 5.2 进位处理公式\n\n对于每一位：\n\n```cpp\nint sum = a[i] + b[i] + carry;  // 两位相加，加上进位\nc[i] = sum % 10;                 // 当前位的结果\ncarry = sum / 10;                // 新的进位\n```\n\n示例：8 + 7 + 1（进位）= 16\n\n- 当前位：16 % 10 = 6\n- 进位：16 / 10 = 1\n\n### 5.3 最后的进位不要忘！\n\n```cpp\n// 循环结束后，如果还有进位\nif (carry > 0) {\n    c[len] = carry;\n    len++;\n}\n```\n\n示例：999 + 1 = 1000\n\n- 最后一位相加产生的进位不能丢！\n\n### 5.4 字符与数字的转换\n\n```cpp\n// 字符 → 数字\nchar ch = '5';\nint digit = ch - '0';  // digit = 5\n\n// 数字 → 字符\nint digit = 5;\nchar ch = digit + '0';  // ch = '5'\n```\n\n---\n\n## 六、完整模板代码\n\n```cpp\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nclass BigInt {\npublic:\n    vector<int> digits;  // 倒序存储\n\n    // 从字符串构造\n    BigInt(string s = \"0\") {\n        for (int i = s.length() - 1; i >= 0; i--) {\n            digits.push_back(s[i] - '0');\n        }\n        removeLeadingZeros();\n    }\n\n    // 去除前导零\n    void removeLeadingZeros() {\n        while (digits.size() > 1 && digits.back() == 0) {\n            digits.pop_back();\n        }\n    }\n\n    // 转为字符串\n    string toString() const {\n        string s = \"\";\n        for (int i = digits.size() - 1; i >= 0; i--) {\n            s += (char)(digits[i] + '0');\n        }\n        return s;\n    }\n\n    // 高精度加法\n    BigInt operator+(const BigInt& other) const {\n        BigInt result;\n        result.digits.clear();\n\n        int carry = 0;\n        int n = max(digits.size(), other.digits.size());\n\n        for (int i = 0; i < n || carry; i++) {\n            int sum = carry;\n            if (i < digits.size()) sum += digits[i];\n            if (i < other.digits.size()) sum += other.digits[i];\n            result.digits.push_back(sum % 10);\n            carry = sum / 10;\n        }\n\n        return result;\n    }\n};\n\nint main() {\n    string a, b;\n    cin >> a >> b;\n\n    BigInt num1(a), num2(b);\n    BigInt sum = num1 + num2;\n\n    cout << sum.toString() << endl;\n\n    return 0;\n}\n```\n\n---\n\n## 七、例题精讲\n\n### 例题1：A + B（高精度版）\n\n**题目**：输入两个正整数 A 和 B，输出 A + B 的结果。（A、B 最多 500 位）\n\n**输入**：\n\n```\n123456789012345678901234567890\n987654321098765432109876543210\n```\n\n**输出**：\n\n```\n1111111110111111111011111111100\n```\n\n**解法**：直接套用高精度加法模板。\n\n### 例题2：多组数据\n\n**题目**：给定 n 组数据，每组两个大整数，求它们的和。\n\n```cpp\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstring add(string num1, string num2) {\n    vector<int> a, b, c;\n\n    for (int i = num1.length() - 1; i >= 0; i--) {\n        a.push_back(num1[i] - '0');\n    }\n    for (int i = num2.length() - 1; i >= 0; i--) {\n        b.push_back(num2[i] - '0');\n    }\n\n    int carry = 0;\n    for (int i = 0; i < a.size() || i < b.size() || carry; i++) {\n        int sum = carry;\n        if (i < a.size()) sum += a[i];\n        if (i < b.size()) sum += b[i];\n        c.push_back(sum % 10);\n        carry = sum / 10;\n    }\n\n    string result = \"\";\n    for (int i = c.size() - 1; i >= 0; i--) {\n        result += (char)(c[i] + '0');\n    }\n    return result;\n}\n\nint main() {\n    int n;\n    cin >> n;\n\n    while (n--) {\n        string a, b;\n        cin >> a >> b;\n        cout << add(a, b) << endl;\n    }\n\n    return 0;\n}\n```\n\n### 例题3：连加\n\n**题目**：输入 n 个大整数，求它们的和。\n\n```cpp\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvector<int> add(vector<int> a, vector<int> b) {\n    vector<int> c;\n    int carry = 0;\n\n    for (int i = 0; i < a.size() || i < b.size() || carry; i++) {\n        int sum = carry;\n        if (i < a.size()) sum += a[i];\n        if (i < b.size()) sum += b[i];\n        c.push_back(sum % 10);\n        carry = sum / 10;\n    }\n\n    return c;\n}\n\nvector<int> stringToVec(string s) {\n    vector<int> v;\n    for (int i = s.length() - 1; i >= 0; i--) {\n        v.push_back(s[i] - '0');\n    }\n    return v;\n}\n\nstring vecToString(vector<int> v) {\n    string s = \"\";\n    for (int i = v.size() - 1; i >= 0; i--) {\n        s += (char)(v[i] + '0');\n    }\n    return s;\n}\n\nint main() {\n    int n;\n    cin >> n;\n\n    vector<int> sum = {0};  // 初始为 0\n\n    for (int i = 0; i < n; i++) {\n        string s;\n        cin >> s;\n        sum = add(sum, stringToVec(s));\n    }\n\n    cout << vecToString(sum) << endl;\n\n    return 0;\n}\n```\n\n---\n\n## 八、常见错误与调试\n\n### 错误1：忘记处理最后的进位\n\n```cpp\n// ❌ 错误\nfor (int i = 0; i < len; i++) {\n    // 加法运算\n}\n\n// ✅ 正确\nfor (int i = 0; i < len || carry; i++) {\n    // 加法运算\n}\n// 或者循环后检查 carry\n```\n\n### 错误2：字符转数字时忘记减 '0'\n\n```cpp\n// ❌ 错误\na[i] = s[i];  // 存的是 ASCII 码！\n\n// ✅ 正确\na[i] = s[i] - '0';\n```\n\n### 错误3：正序存储导致对齐错误\n\n```cpp\n// ❌ 错误：正序存储\n// 123 → a = [1, 2, 3]\n// 45  → b = [4, 5]\n\n// ✅ 正确：倒序存储\n// 123 → a = [3, 2, 1]\n// 45  → b = [5, 4]\n```\n\n---\n\n## 九、本课小结\n\n### 核心算法\n\n```\n高精度加法 = 字符串转数组(倒序) + 逐位相加 + 处理进位 + 转回字符串\n```\n\n### 关键公式\n\n```cpp\nsum = a[i] + b[i] + carry;\nc[i] = sum % 10;\ncarry = sum / 10;\n```\n\n### 代码要点\n\n- ✅ 倒序存储大数\n- ✅ 逐位相加，处理进位\n- ✅ 不要忘记最后的进位\n- ✅ 字符与数字互转\n\n---\n\n## 十、课后思考\n\n1. 如果两个数都是 0，输出应该是什么？\n2. 如果输入的数有前导零（如 \"007\"），该怎么处理？\n3. 高精度加法的时间复杂度是多少？\n\n---\n\n**下节预告**：第5课 - 高精度减法，比加法多了哪些坑？\n";export{n as default};
